function Greeting({ name }) {
  return <h2 style={{ fontFamily: 'system-ui' }}>Hello, {name}!</h2>;
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <Greeting name="Ada" />
      <Greeting name="Linus" />
      <Greeting name="Grace" />
    </div>
  );
}

function Card({ title, children }) {
  return (
    <div style={{ border: '1px solid #ccc', borderRadius: 8, padding: 16, margin: 8, fontFamily: 'system-ui' }}>
      <h3 style={{ marginTop: 0 }}>{title}</h3>
      {children}
    </div>
  );
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <Card title="Welcome">
        <p>Anything I nest here becomes the children prop.</p>
        <button>Click me</button>
      </Card>
      <Card title="Tips">
        <ul><li>Compose small pieces</li><li>Keep props read-only</li></ul>
      </Card>
    </div>
  );
}

