solution.code:
function UserBadge({ name, role = 'Member' }) {
  return <p style={{ fontFamily: 'system-ui' }}><strong>{name}</strong> — {role}</p>;
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <UserBadge name="Ada" role="Admin" />
      <UserBadge name="Linus" />
    </div>
  );
}
